import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import jwt from 'jsonwebtoken';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: false } : false
});

const JWT_SECRET = process.env.JWT_SECRET || 'dev-secret-key';

// Middleware: extract user from JWT
function authenticate(req, res, next) {
  const token = req.headers.authorization?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'No token' });
  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

// Search documents endpoint - supports full-text search with filters
app.get('/api/documents/search', authenticate, async (req, res) => {
  const { q, category, sort_by, order } = req.query;
  const userId = req.user.sub;

  // Base query with parameterized user filter
  let query = `SELECT id, title, snippet, category, created_at 
               FROM documents 
               WHERE owner_id = $1 AND archived = false`;
  let params = [userId];
  let paramIdx = 2;

  if (category) {
    query += ` AND category = $${paramIdx}`;
    params.push(category);
    paramIdx++;
  }

  if (q) {
    query += ` AND (title ILIKE $${paramIdx} OR content ILIKE $${paramIdx})`;
    params.push(`%${q}%`);
    paramIdx++;
  }

  // Sort - validated against allowlist... or so it appears
  const allowedSorts = ['created_at', 'title', 'updated_at', 'relevance'];
  const sortField = allowedSorts.includes(sort_by) ? sort_by : 'created_at';
  const sortOrder = order === 'asc' ? 'ASC' : 'DESC';

  query += ` ORDER BY ${sortField} ${sortOrder} LIMIT 50`;

  try {
    const result = await pool.query(query, params);
    res.json({ documents: result.rows });
  } catch (e) {
    res.status(500).json({ error: 'Search failed' });
  }
});

// Export documents - generates CSV with custom column selection
app.post('/api/documents/export', authenticate, async (req, res) => {
  const { document_ids, columns, format_options } = req.body;
  const userId = req.user.sub;

  if (!document_ids || !Array.isArray(document_ids)) {
    return res.status(400).json({ error: 'document_ids required' });
  }

  // Build column list from user input
  const defaultCols = ['id', 'title', 'category', 'created_at'];
  const requestedCols = columns && Array.isArray(columns) ? columns : defaultCols;

  // Column validation - check they look like identifiers
  const colRegex = /^[a-zA-Z_][a-zA-Z0-9_.()" ]*$/;
  const validatedCols = requestedCols.filter(c => colRegex.test(c) && c.length < 64);

  if (validatedCols.length === 0) {
    return res.status(400).json({ error: 'No valid columns' });
  }

  const colList = validatedCols.join(', ');
  const placeholders = document_ids.map((_, i) => `$${i + 2}`).join(',');

  const query = `SELECT ${colList} FROM documents WHERE owner_id = $1 AND id IN (${placeholders})`;
  const params = [userId, ...document_ids];

  try {
    const result = await pool.query(query, params);

    if (format_options?.format === 'csv') {
      const header = validatedCols.join(',');
      const rows = result.rows.map(r => validatedCols.map(c => r[c] ?? '').join(','));
      res.setHeader('Content-Type', 'text/csv');
      res.send([header, ...rows].join('\n'));
    } else {
      res.json({ data: result.rows });
    }
  } catch (e) {
    res.status(500).json({ error: 'Export failed' });
  }
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.listen(process.env.PORT || 3000);
